.table-chat{padding:19px;border-color:rgba(145,156,205,.2);border-radius:22px;background:radial-gradient(ellipse at 100% 0,rgba(0,239,135,.055),transparent 40%),linear-gradient(145deg,#171d35,#10152a);box-shadow:0 14px 34px rgba(0,0,0,.12)}.table-chat__head h2{font-size:16px}.table-chat__head p{font-size:11px}.table-chat__messages{min-height:190px;max-height:430px;gap:12px;padding:15px;border-radius:18px;background:radial-gradient(circle at 15% 15%,rgba(90,107,158,.08),transparent 40%),#0d1225}.table-chat__message{padding:10px 13px;border-radius:17px 17px 17px 5px;background:#202844;box-shadow:0 3px 12px rgba(0,0,0,.13)}.table-chat__message.is-mine{border-color:rgba(0,239,135,.22);border-radius:17px 17px 5px 17px;background:linear-gradient(135deg,rgba(0,239,135,.14),rgba(0,155,105,.1))}.table-chat__meta{align-items:center;font-size:10px}.table-chat__body{font-size:13px;line-height:1.55}.table-chat__tools{gap:9px;margin-bottom:10px}.table-chat__file,.table-chat__voice{min-height:39px;border-radius:13px;font-size:12px;transition:background .18s,border-color .18s,color .18s}.table-chat__file:hover,.table-chat__voice:hover{border-color:rgba(0,239,135,.45);background:rgba(0,239,135,.08);color:var(--tm-green)}.table-chat__form{align-items:flex-end;gap:10px;padding:9px;border-color:rgba(145,156,205,.22);border-radius:19px;background:#10162b;transition:border-color .18s,box-shadow .18s}.table-chat__form:focus-within{border-color:rgba(0,239,135,.58);box-shadow:0 0 0 3px rgba(0,239,135,.08)}.table-chat__form textarea{min-height:40px;max-height:160px;overflow-y:hidden;resize:none;padding:9px 10px;font-size:14px;line-height:1.5}.table-chat__form textarea::placeholder{color:#828daf;opacity:1}.table-chat__send{width:43px;height:43px;flex-basis:43px;border-radius:15px;box-shadow:0 5px 15px rgba(0,239,135,.16);transition:filter .18s,transform .18s}.table-chat__send:hover{filter:brightness(1.08);color:#062b1d;transform:translateY(-1px)}.table-chat__reactions button{min-height:28px;border-radius:16px;background:rgba(12,18,37,.7);transition:border-color .16s,background .16s}.table-chat__reactions button:hover{border-color:rgba(0,239,135,.48);background:rgba(0,239,135,.1);color:var(--tm-text)}
@media(max-width:575px){.table-match__invite{padding:15px}.table-match__invite-control{gap:7px}.table-match__invite input{height:45px;font-size:13px}.table-match__invite button{padding:0 12px}.table-chat{padding:14px}.table-chat__messages{min-height:170px;max-height:48vh;padding:11px}.table-chat__form{padding:7px}.table-chat__form textarea{font-size:14px}.table-chat__send{width:40px;height:40px;flex-basis:40px}}
</style>
@endpush
@push('script')
<script>
(()=>{const root=document.querySelector('#table-match');if(!root)return;const stateUrl=root.dataset.snapshot;const api={move:root.dataset.move,start:root.dataset.start,leave:root.dataset.leave};const board=document.querySelector('#table-board');const error=document.querySelector('#match-error');const notice=document.querySelector('#match-notice');const userId=Number(root.dataset.user);const type=root.dataset.type;let latest=null,clockTimer=null,polling=false,pollTimer=null;
const rules={ludo:'Roll a six to bring a token out of home. Six gives another roll. Landing on an opposing token captures it and sends it home. Finish all four tokens with an exact roll. The first player to finish wins.',chess:'Standard chess: legal moves, check/checkmate/stalemate, castling, en passant, promotion, draw offers and resignations. The server enforces each turn timer; a timeout forfeits the game.',draughts:'8x8 short-king draughts: captures are mandatory, men may capture forward or backward, and a capturing piece must finish available multi-jumps. Kings move one diagonal square. An 80-ply run without a capture or promotion is a draw.',tic_tac_toe:'Take turns placing X and O. Three in a row wins. A full board with no line is a draw, and stakes are returned.',four_in_a_row:'Drop one checker into a column. Four connected horizontally, vertically, or diagonally wins. A full board with no line is a draw.',snakes_and_ladders:'Take turns rolling the server-generated die. Ladders move you up, snakes move you down, and you must land exactly on 100 to win.',oware:'Standard two-row Oware: sow anticlockwise, feed the opponent when possible, and capture backward from their side only while the capture does not take their last seeds. The round ends at 25 seeds, when a side cannot move, or at the move cap; remaining seeds are counted. Equal scores draw and stakes are returned.'};rules.dominoes='Use a standard double-six set. Play a tile that matches either open end, draw until you can play or the stock is empty, then pass only when blocked. Empty your hand to win; if play is blocked, the fewest remaining pips wins. A tie is a draw.';rules.crazy_eights='Use a standard 52-card deck. Play a card matching the top rank or suit; an eight is wild and lets you choose the next suit. Draw when blocked. The first empty hand wins; if no cards remain and everyone is blocked, the table is a draw.';rules.sea_battle='Each player has a hidden server-placed fleet on a 10×10 grid. Fire one shot per turn at the target grid. Hits and misses are revealed after each shot; the first to hit all 17 fleet cells wins. Boards are generated and kept on the server.';rules.blackjack='Player-versus-player Blackjack: each player receives two private cards, then chooses Hit or Stand on their turn. Aces count as 1 or 11; face cards count as 10. The highest total at or below 21 wins; equal best totals and all-bust rounds are draws. Cards are shuffled server-side.';rules.rummy='Seven-card draw rummy: draw from the stock or discard, then discard one card. A valid winning hand partitions fully into 3+ card runs of one suit or sets of the same rank. The server shuffles and validates all cards.';rules.whot='Nigerian Whot: match the top number or active shape; Whot 20 is wild and names the next shape. Special cards: 1 Hold On (play again), 2 Pick Two, 5 Pick Three (the next player draws and is skipped), 8 Suspension (skip next player), 14 General Market (each other player draws one and you play again). Penalty cards do not stack in this table. Draw when blocked; first empty hand wins.';document.querySelector('#match-rules').textContent=rules[type]||'Follow the standard rules shown in the game guide.';
function gameState(data){latest=data;document.querySelector('#match-status').textContent=data.status[0].toUpperCase()+data.status.slice(1);if(['finished','cancelled','force_closed'].includes(data.status)){if(pollTimer){clearInterval(pollTimer);pollTimer=null;}if(clockTimer){clearInterval(clockTimer);clockTimer=null;}}const active=data.status==='active';notice.textContent=data.status==='waiting'?'Waiting for all seats or the creator to start with at least two players.':data.status==='finished'?(data.result==='draw'?'Game drawn.':`Game complete  ${(data.result.startsWith('winners:')?data.result.slice(8).split(',').map(seat=>data.players.find(p=>p.seat===Number(seat))?.name).filter(Boolean).join(' and '):data.players.find(p=>`winner:${p.seat}`===data.result)?.name)||'winner'} won.`):data.status==='cancelled'?'This table expired and its stakes were refunded.':data.current_user_id===userId?'Your turn. Choose a move.':`Waiting for ${data.players.find(p=>p.id===data.current_user_id)?.name||'your opponent'}`;
const players=document.querySelector('#match-players');players.replaceChildren();data.players.forEach(player=>{const row=document.createElement('div');row.className='match-player'+(active&&player.id===data.current_user_id?' is-turn':'');const avatar=document.createElement('span');avatar.className='match-player__avatar';avatar.textContent=String(player.seat+1);const name=document.createElement('strong');name.textContent=player.name||`Player ${player.seat+1}`;const status=document.createElement('small');status.textContent=player.status==='out'?'Out':player.id===data.current_user_id?'Playing':'Seated';row.append(avatar,name,status);players.append(row);});renderBoard(data);document.querySelector('#match-start').hidden=!(data.status==='waiting'&&data.players.filter(p=>p.status==='seated').length>=2&&data.players.some(p=>p.id===userId&&p.seat===0));document.querySelector('#match-leave').hidden=!['waiting','active'].includes(data.status);const inviteForm=document.querySelector('#match-invite');if(inviteForm)inviteForm.hidden=data.status!=='waiting';if(data.turn_deadline_at){const deadline=Date.parse(data.turn_deadline_at);clearInterval(clockTimer);clockTimer=setInterval(()=>{const left=Math.max(0,Math.ceil((deadline-Date.now())/1000));document.querySelector('#turn-clock').innerHTML=`<i class="las la-hourglass-half"></i> <b>${left}s</b>`;},250);}else document.querySelector('#turn-clock').innerHTML='<i class="las la-hourglass-half"></i> <b>--</b>';}
function send(action){if(!latest||latest.status!=='active'||latest.current_user_id!==userId)return;error.textContent='';fetch(api.move,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':root.dataset.csrf},body:JSON.stringify({action,version:latest.version,idempotency_key:crypto.randomUUID()})}).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.message||'Move could not be made.');return refresh();}).catch(e=>{error.textContent=e.message;});}
function renderBoard(data) {
    board.replaceChildren();
    const active = data.status === 'active' && data.current_user_id === userId;
    const state = data.state || {};
    const makeActionRow = () => { const row = document.createElement('div'); row.className = 'board-action-row'; return row; };
    if (type === 'spades' || type === 'hearts') {
        const seat=latest.players.find(p=>p.id===userId)?.seat||0;const suitNames={S:'♠',H:'♥',D:'♦',C:'♣'};const guide=document.createElement('p');guide.className='board-scorebar';guide.textContent=type==='spades'?'Four-player partnership Spades: seats 1+3 and 2+4 form teams. Bid nil or 1–13, follow suit, and spades trump. One hand; contract points decide the winning team.':'Four-player Hearts: follow suit, avoid hearts and the queen of spades. Hearts cannot be led before broken. After one hand, the player with the fewest penalty points wins. No card passing.';board.append(guide);const stats=document.createElement('div');stats.className='board-scorebar';latest.players.forEach(player=>{const item=document.createElement('span');item.textContent=type==='spades'?`P${player.seat+1} bid ${state.bids?.[player.seat]??'—'} · tricks ${state.tricks_won?.[player.seat]||0}`:`P${player.seat+1} · points ${state.scores?.[player.seat]||0}`;stats.append(item);});board.append(stats);if(type==='spades'&&state.phase==='bid'&&active){const controls=document.createElement('div');controls.className='board-select-row';const bid=document.createElement('select');for(let value=0;value<=13;value++){const option=document.createElement('option');option.value=String(value);option.textContent=value===0?'Nil':`Bid ${value}`;bid.append(option);}const submit=document.createElement('button');submit.type='button';submit.className='table-match__start';submit.textContent='Submit bid';submit.onclick=()=>send({type:'bid',bid:Number(bid.value)});controls.append(bid,submit);board.append(controls);}const trick=document.createElement('div');trick.className='board-card-hand';(state.trick||[]).forEach(play=>{const card=document.createElement('span');card.className='board-card';card.textContent=`P${play.seat+1} · ${play.card.rank}${suitNames[play.card.suit]||''}`;trick.append(card);});board.append(trick);const hand=document.createElement('div');hand.className='board-card-hand';const own=state.hands?.[seat]||[];const leadSuit=state.trick?.[0]?.card?.suit;const canFollow=leadSuit&&own.some(card=>card.suit===leadSuit);const opening=state.moves<4;own.forEach((card,index)=>{let legal=!canFollow||card.suit===leadSuit;if(opening&&seat===state.first_player&&!state.trick.length)legal=card.rank==='2'&&card.suit==='C';if(type==='spades'&&state.trick.length===0&&!state.spades_broken&&card.suit==='S'&&own.some(item=>item.suit!=='S'))legal=false;if(type==='hearts'&&state.trick.length===0&&!state.hearts_broken&&card.suit==='H'&&own.some(item=>item.suit!=='H'))legal=false;if(type==='hearts'&&opening&&(card.suit==='H'||(card.suit==='S'&&card.rank==='Q'))&&own.some(item=>item.suit!=='H'&&!(item.suit==='S'&&item.rank==='Q')))legal=false;const button=document.createElement('button');button.type='button';button.className='board-card';button.textContent=`${card.rank}${suitNames[card.suit]||''}`;button.disabled=!active||state.phase!=='play'||!legal;button.onclick=()=>send({type:'play',card:index});hand.append(button);});board.append(hand);
    } else if (type === 'texas_holdem') {
        const suitNames={S:'♠',H:'♥',D:'♦',C:'♣'};const seat=latest.players.find(p=>p.id===userId)?.seat||0;const title=document.createElement('p');title.className='board-scorebar';title.textContent=`${String(state.street||'Preflop').toUpperCase()} · Fixed-stake showdown (no side bets)`;board.append(title);const community=document.createElement('div');community.className='board-card-hand';(state.board||[]).forEach(card=>{const node=document.createElement('span');node.className='board-card';node.textContent=`${card.rank}${suitNames[card.suit]||''}`;community.append(node);});board.append(community);const hand=document.createElement('div');hand.className='board-card-hand';(state.private_hand||[]).forEach(card=>{const node=document.createElement('span');node.className='board-card';node.textContent=`${card.rank}${suitNames[card.suit]||''}`;hand.append(node);});board.append(hand);const progress=document.createElement('div');progress.className='board-scorebar';latest.players.forEach(player=>{const label=document.createElement('span');label.textContent=`${player.name||'Player '+(player.seat+1)} · ${state.checked?.includes(player.seat)?'checked':'to act'}`;progress.append(label);});board.append(progress);if(active){const check=document.createElement('button');check.type='button';check.className='table-match__start';check.textContent='Check';check.onclick=()=>send({type:'check'});board.append(check);}
    } else if (type === 'backgammon') {
        const guide=document.createElement('p');guide.className='board-scorebar';guide.textContent='Move 15 checkers home, hit single opposing checkers, and bear off. If a checker is on the bar, re-enter it first.';board.append(guide);const seat=latest.players.find(p=>p.id===userId)?.seat||0;const boardView=document.createElement('div');boardView.className='board-grid board-grid--bg';const indices=seat===0?Array.from({length:24},(_,i)=>i):Array.from({length:24},(_,i)=>23-i);indices.forEach(index=>{const count=state.points?.[index]||0;const own=count*(seat===0?1:-1)>0;const cell=document.createElement('div');cell.className='board-cell board-cell--bg'+(own?' is-own':'');cell.textContent=`${index+1} · ${count===0?'—':Math.abs(count)+(own?'●':'○')}`;boardView.append(cell);});board.append(boardView);const status=document.createElement('p');status.className='board-scorebar';status.textContent=`Bar: you ${state.bar?.[seat]||0} · opponent ${state.bar?.[1-seat]||0}  |  Off: you ${state.off?.[seat]||0} · opponent ${state.off?.[1-seat]||0}  |  Dice: ${(state.dice||[]).join(', ')||'not rolled'}`;board.append(status);if(active){if(state.dice===null){const roll=document.createElement('button');roll.type='button';roll.className='table-match__start';roll.textContent='Roll dice';roll.onclick=()=>send({type:'roll'});board.append(roll);}else if(state.dice.length){const controls=document.createElement('div');controls.className='board-select-row';const from=document.createElement('select');const barOption=document.createElement('option');barOption.value='-1';barOption.textContent='From bar';if(!state.bar?.[seat])barOption.disabled=true;from.append(barOption);state.points?.forEach((count,index)=>{if(count*(seat===0?1:-1)>0){const option=document.createElement('option');option.value=String(index);option.textContent=`Point ${index+1} (${Math.abs(count)} checkers)`;from.append(option);}});const die=document.createElement('select');[...new Set(state.dice)].forEach(value=>{const option=document.createElement('option');option.value=String(value);option.textContent=`Die ${value}`;die.append(option);});const move=document.createElement('button');move.type='button';move.className='table-match__start';move.textContent='Move checker';move.onclick=()=>send({type:'move',from:Number(from.value),die:Number(die.value)});controls.append(from,die,move);board.append(controls);}}
    } else if (type === 'whot') {
        const seat=latest.players.find(p=>p.id===userId)?.seat||0;const top=state.discard?.at(-1)||{};const hand=state.hands?.[seat]||[];const playable=card=>card.number===20||card.number===top.number||card.shape===state.active_shape;const pile=document.createElement('div');pile.className='board-card-pile';pile.textContent=`${top.shape||'—'} ${top.number||''} · Active shape: ${state.active_shape} · Stock ${state.stock?.length||0}`;board.append(pile);if(active&&hand.some(card=>card.number===20)){const shape=document.createElement('select');shape.id='whot-shape';shape.className='board-card-suit';['Circle','Triangle','Cross','Square','Star'].forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;shape.append(option);});board.append(shape);}const cards=document.createElement('div');cards.className='board-card-hand';hand.forEach((card,index)=>{const button=document.createElement('button');button.type='button';button.className='board-card';button.textContent=card.number===20?'WHOT 20':`${card.number} ${card.shape}`;button.disabled=!active||!playable(card);button.onclick=()=>send({type:'play',card:index,...(card.number===20?{shape:document.querySelector('#whot-shape')?.value}:{})});cards.append(button);});board.append(cards);if(active&&!hand.some(playable)&&state.stock?.length){const draw=document.createElement('button');draw.type='button';draw.className='table-match__start';draw.textContent='Draw a card';draw.onclick=()=>send({type:'draw'});board.append(draw);}if(!active){const counts=document.createElement('p');counts.textContent=(state.hand_counts||[]).map((count,index)=>`Player ${index+1}: ${count} cards`).join(' · ');board.append(counts);}
    } else if (type === 'rummy') {
        const seat=latest.players.find(p=>p.id===userId)?.seat||0;const cards=state.hands?.[seat]||[];const suitNames={S:'♠',H:'♥',D:'♦',C:'♣'};const pile=document.createElement('div');pile.className='board-card-pile';pile.textContent=`Discard pile: ${state.discard?.at(-1)?.rank||'—'} ${suitNames[state.discard?.at(-1)?.suit]||''} · Stock ${state.stock?.length||0}`;board.append(pile);const hand=document.createElement('div');hand.className='board-card-hand';cards.forEach((card,index)=>{const button=document.createElement('button');button.type='button';button.className='board-card';button.textContent=`${card.rank}${suitNames[card.suit]||''}`;button.disabled=!active||state.phase!=='discard';button.onclick=()=>send({type:'discard',card:index});hand.append(button);});board.append(hand);if(active&&state.phase==='draw'){const stock=document.createElement('button');stock.type='button';stock.className='table-match__start';stock.textContent='Draw from stock';stock.onclick=()=>send({type:'draw_stock'});const discard=document.createElement('button');discard.type='button';discard.className='table-match__leave';discard.textContent='Take discard';discard.disabled=(state.discard||[]).length<2;discard.onclick=()=>send({type:'draw_discard'});board.append(stock,discard);}if(!active){const counts=document.createElement('p');counts.textContent=(state.hand_counts||[]).map((count,index)=>`Player ${index+1}: ${count} cards`).join(' · ');board.append(counts);}
    } else if (type === 'blackjack') {
        const seat=latest.players.find(p=>p.id===userId)?.seat||0;const suitNames={S:'♠',H:'♥',D:'♦',C:'♣'};const title=document.createElement('p');title.className='board-scorebar';title.textContent='Your hand';board.append(title);const handBox=document.createElement('div');handBox.className='board-card-hand';(state.hands?.[seat]||[]).forEach(card=>{const node=document.createElement('span');node.className='board-card';node.textContent=`${card.rank}${suitNames[card.suit]||''}`;handBox.append(node);});board.append(handBox);const totals=document.createElement('div');totals.className='board-scorebar';(latest.players||[]).forEach(player=>{const label=document.createElement('span');const total=state.hand_totals?.[player.seat];label.textContent=`${player.name||'Player '+(player.seat+1)} · ${state.stood?.[player.seat]?'stood':player.status==='out'?'out':'playing'} · ${total??'—'}`;totals.append(label);});board.append(totals);if(active&&!state.stood?.[seat]){const hit=document.createElement('button');hit.type='button';hit.className='table-match__start';hit.textContent='Hit';hit.onclick=()=>send({type:'hit'});const stand=document.createElement('button');stand.type='button';stand.className='table-match__leave';stand.textContent='Stand';stand.onclick=()=>send({type:'stand'});board.append(hit,stand);}
    } else if (type === 'sea_battle') {
        const seat=latest.players.find(p=>p.id===userId)?.seat||0;const myShots=new Map((state.my_shots||[]).map(shot=>[shot.cell,shot]));const incoming=new Map((state.incoming_shots||[]).map(shot=>[shot.cell,shot]));
        const heading=document.createElement('p');heading.className='board-scorebar';heading.textContent='Your fleet';board.append(heading);const own=document.createElement('div');own.className='board-grid board-grid--sea';(state.own_board||[]).forEach((row,r)=>row.forEach((ship,c)=>{const cell=document.createElement('div');const shot=incoming.get(`${r}:${c}`);cell.className='board-cell board-cell--sea'+(ship!==null?' is-ship':'')+(shot?(shot.hit?' is-hit':' is-miss'):'');cell.textContent=shot?(shot.hit?'✦':'·'):ship!==null?'▰':'';own.append(cell);}));board.append(own);
        const targetTitle=document.createElement('p');targetTitle.className='board-scorebar';targetTitle.textContent='Target waters';board.append(targetTitle);const target=document.createElement('div');target.className='board-grid board-grid--sea';for(let r=0;r<10;r++)for(let c=0;c<10;c++){const shot=myShots.get(`${r}:${c}`);const cell=document.createElement('button');cell.type='button';cell.className='board-cell board-cell--sea'+(shot?(shot.hit?' is-hit':' is-miss'):'');cell.textContent=shot?(shot.hit?'✦':'·'):'';cell.disabled=!active||!!shot;cell.onclick=()=>send({row:r,col:c});target.append(cell);}board.append(target);
    } else if (type === 'tic_tac_toe') {
        const grid = document.createElement('div'); grid.className = 'board-grid board-grid--xo';
        state.board?.forEach((value, index) => { const cell = document.createElement('button'); cell.type='button'; cell.className=`board-cell${value!==null?' is-seat-'+(value+1):''}`; cell.textContent=value===null?'':value===0?'X':'O'; cell.disabled=!active||value!==null; cell.onclick=()=>send({cell:index}); grid.append(cell); }); board.append(grid);
    } else if (type === 'four_in_a_row') {
        const grid = document.createElement('div'); grid.className='board-grid board-grid--connect';
        for(let column=0;column<7;column++){const button=document.createElement('button');button.type='button';button.className='board-cell board-cell--connect';button.textContent='';button.disabled=!active||state.board?.[0]?.[column]!==null;button.onclick=()=>send({column});grid.append(button);}
        state.board?.forEach(row=>row.forEach(value=>{const cell=document.createElement('div');cell.className=`board-cell board-cell--connect${value===null?'':' is-seat-'+(value+1)}`;cell.textContent=value===null?'':'';grid.append(cell);}));board.append(grid);
    } else if (type === 'crazy_eights') {
        const seat=latest.players.find(player=>player.id===userId)?.seat||0;const top=state.top||{};const suitNames={S:'Spades',H:'Hearts',D:'Diamonds',C:'Clubs'};const pile=document.createElement('div');pile.className='board-card-pile';pile.textContent=`Top card: ${top.rank||'?'} of ${suitNames[state.current_suit]||'?'}`;board.append(pile);
        const hand=state.hands?.[seat]||[];const canPlay=hand.some(card=>card.rank==='8'||card.rank===top.rank||card.suit===state.current_suit);
        if(active){const suit=document.createElement('select');suit.className='board-card-suit';[['S','Spades'],['H','Hearts'],['D','Diamonds'],['C','Clubs']].forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;suit.append(option);});board.append(suit);const cards=document.createElement('div');cards.className='board-card-hand';hand.forEach((card,index)=>{const button=document.createElement('button');button.type='button';button.className='board-card';button.textContent=`${card.rank} ${card.suit}`;button.disabled=!(card.rank==='8'||card.rank===top.rank||card.suit===state.current_suit);button.onclick=()=>send({type:'play',card:index,...(card.rank==='8'?{suit:suit.value}:{})});cards.append(button);});board.append(cards);
            if(!canPlay&&(state.stock?.length||(state.discard||[]).length>1)){const draw=document.createElement('button');draw.type='button';draw.className='table-match__start';draw.textContent='Draw a card';draw.onclick=()=>send({type:'draw'});board.append(draw);}else if(!canPlay&&(!state.stock?.length)&&(state.discard||[]).length<=1){const pass=document.createElement('button');pass.type='button';pass.className='table-match__leave';pass.textContent='Pass';pass.onclick=()=>send({type:'pass'});board.append(pass);}
        }else{const counts=document.createElement('p');counts.textContent=(state.hand_counts||[]).map((count,index)=>`Player ${index+1}: ${count} cards`).join('  ');board.append(counts);}
    } else if (type === 'dominoes') {
        const seat=latest.players.find(player=>player.id===userId)?.seat||0;const chain=document.createElement('div');chain.className='board-domino-chain';(state.chain||[]).forEach(tile=>{const node=document.createElement('span');node.textContent=`${tile[0]} | ${tile[1]}`;chain.append(node);});board.append(chain);
        const hand=state.hands?.[seat]||[];const ends=state.ends;const canPlay=hand.some(tile=>!ends||tile.includes(ends[0])||tile.includes(ends[1]));
        if(active){const handBox=document.createElement('div');handBox.className='board-domino-hand';hand.forEach((tile,index)=>{const sides=ends?['left','right']:['right'];sides.forEach(side=>{const button=document.createElement('button');button.type='button';button.textContent=`${tile[0]} | ${tile[1]}${ends?'  '+side:''}`;button.disabled=ends&&!tile.includes(ends[side==='left'?0:1]);button.onclick=()=>send({type:'play',tile:index,end:side});handBox.append(button);});});board.append(handBox);
            if(!canPlay&&(state.stock?.length||(state.discard||[]).length>1)){const draw=document.createElement('button');draw.type='button';draw.className='table-match__start';draw.textContent=`Draw from stock (${state.stock.length})`;draw.onclick=()=>send({type:'draw'});board.append(draw);}else if(!canPlay){const pass=document.createElement('button');pass.type='button';pass.className='table-match__leave';pass.textContent='Pass';pass.onclick=()=>send({type:'pass'});board.append(pass);}
        }else{const counts=document.createElement('p');counts.textContent=(state.hand_counts||[]).map((count,index)=>`Player ${index+1}: ${count} tiles`).join('  ');board.append(counts);}
    } else if (type === 'oware') {
        const scorebar=document.createElement('div');scorebar.className='board-scorebar';(state.scores||[]).forEach((score,index)=>{const label=document.createElement('span');label.textContent="Player "+(index+1)+": "+score;scorebar.append(label);});const pits=document.createElement('div');pits.className='board-pits';const seat=latest.players.find(p=>p.id===userId)?.seat||0;const order=seat===0?[11,10,9,8,7,6,0,1,2,3,4,5]:[5,4,3,2,1,0,6,7,8,9,10,11];
        order.forEach(index=>{const button=document.createElement('button');button.type='button';button.className='board-pit';button.textContent=state.pits?.[index]??0;const own=seat===0?index<6:index>=6;button.disabled=!active||!own||!state.pits?.[index];button.onclick=()=>send({pit:index});pits.append(button);});board.append(scorebar,pits);
    } else if (type === 'snakes_and_ladders') {
        const track=document.createElement('div');track.className='board-track';for(let index=100;index>=1;index--){const cell=document.createElement('div');cell.className='board-square';cell.textContent=`${index}${Object.hasOwn(state.ladders||{},index)?'+':Object.hasOwn(state.snakes||{},index)?'v':''}`;state.positions?.forEach((position,seat)=>{if(position===index){const token=document.createElement('i');token.className='board-token';token.style.background=seat===0?'#00ef87':'#ffcc70';cell.append(token);}});track.append(cell);}board.append(track);
        if(active){const roll=document.createElement('button');roll.type='button';roll.className='table-match__start';roll.textContent='Roll server die';roll.onclick=()=>send({roll:true});board.append(roll);}
    } else if (type === 'ludo') {
        const seat=latest.players.find(p=>p.id===userId)?.seat||0;
        if(active&&state.pending_roll===null){const roll=document.createElement('button');roll.type='button';roll.className='table-match__start';roll.textContent='Roll server die';roll.onclick=()=>send({roll:true});board.append(roll);}
        if(active&&state.pending_roll!==null){const label=document.createElement('p');label.textContent=`Server roll: ${state.pending_roll}. Choose a movable token.`;board.append(label);const tokens=document.createElement('div');tokens.className='board-grid board-grid--ludo';state.tokens?.[seat]?.forEach((position,index)=>{const token=document.createElement('button');token.type='button';token.className='board-token-button';token.textContent=position===-1?'Home':position===58?'Finished':`Token ${index+1}  ${position}`;token.disabled=position===58||(position===-1&&state.pending_roll!==6)||(position>=0&&position+state.pending_roll>57);token.onclick=()=>send({token:index});tokens.append(token);});board.append(tokens);}
        if(!active){const positions=document.createElement('p');positions.textContent=state.tokens?.map((tokens,index)=>`Player ${index+1}: ${tokens.filter(p=>p===58).length}/4 finished`).join('  ')||'';board.append(positions);}
    } else if (type === 'chess' || type === 'draughts') {
        const seat=latest.players.find(p=>p.id===userId)?.seat||0;const white=seat===0;const grid=document.createElement('div');grid.className='board-grid board-grid--chess';
        const symbols=type==='chess'?{K:'K',Q:'Q',R:'R',B:'B',N:'N',P:'P',k:'k',q:'q',r:'r',b:'b',n:'n',p:'p'}:{w:'o',W:'W',b:'x',B:'X'};
        for(let viewRow=0;viewRow<8;viewRow++)for(let viewCol=0;viewCol<8;viewCol++){const row=white?viewRow:7-viewRow,col=white?viewCol:7-viewCol,piece=state.board?.[row]?.[col]??null,square=String.fromCharCode(97+col)+(8-row);const cell=document.createElement('button');cell.type='button';cell.className=`board-cell board-cell--chess${(row+col)%2?' is-dark':''}${selectedSquare===square?' board-cell--selected':''}`;cell.textContent=piece?symbols[piece]||piece:'';cell.disabled=!active;const own=piece&&(type==='chess'?(seat===0?piece===piece.toUpperCase():piece===piece.toLowerCase()):(seat===0?piece.toLowerCase()==='w':piece.toLowerCase()==='b'));cell.onclick=()=>{if(!selectedSquare){if(own)selectedSquare=square;}else{const from=selectedSquare;selectedSquare=null;if(from!==square)send({from,to:square,promotion:'q'});else if(own)selectedSquare=square;}renderBoard(latest);};grid.append(cell);}board.append(grid);
        if(type==='chess'){const actions=makeActionRow();if(state.draw_offer!==null&&state.draw_offer!==seat){const accept=document.createElement('button');accept.textContent='Accept draw';accept.onclick=()=>send({type:'accept_draw'});const decline=document.createElement('button');decline.textContent='Decline draw';decline.onclick=()=>send({type:'decline_draw'});actions.append(accept,decline);}else if(active){const offer=document.createElement('button');offer.textContent='Offer draw';offer.onclick=()=>send({type:'offer_draw'});const resign=document.createElement('button');resign.textContent='Resign';resign.onclick=()=>send({type:'resign'});actions.append(offer,resign);}if(actions.childNodes.length)board.append(actions);}
    }
}
async function refresh(){if(polling)return;polling=true;try{const url=new URL(stateUrl,location.href);if(latest)url.searchParams.set('since',latest.version);const response=await fetch(url,{headers:{'Accept':'application/json'},cache:'no-store'});if(!response.ok)throw new Error('Could not reconnect to this table.');const data=await response.json();if(!data.unchanged)gameState(data);}catch(e){error.textContent=e.message;}finally{polling=false;}}
document.querySelector('#match-start').onclick=()=>fetch(api.start,{method:'POST',headers:{'X-CSRF-TOKEN':root.dataset.csrf,'Accept':'application/json'}}).then(refresh).catch(()=>{});document.querySelector('#match-leave').onclick=()=>{if(confirm(root.dataset.friendly==='1'?'Leave this friendly game? No money is involved.':'Stand up from this table? Your stake will remain in the pot.'))fetch(api.leave,{method:'POST',headers:{'X-CSRF-TOKEN':root.dataset.csrf,'Accept':'application/json'}}).then(refresh);};const inviteForm=document.querySelector('#match-invite');if(inviteForm){const input=inviteForm.querySelector('[name=username]'),suggestions=document.querySelector('#invite-suggestions'),message=document.querySelector('#invite-message'),button=inviteForm.querySelector('button');let searchTimer,searchController;function closeSuggestions(){suggestions.replaceChildren();suggestions.hidden=true;input.setAttribute('aria-expanded','false');}input.setAttribute('aria-expanded','false');input.addEventListener('input',()=>{clearTimeout(searchTimer);searchController?.abort();const query=input.value.trim();message.textContent='';if(!query){closeSuggestions();return;}suggestions.hidden=false;suggestions.innerHTML='<span class="table-match__suggestion-note">Searching players…</span>';input.setAttribute('aria-expanded','true');searchTimer=setTimeout(async()=>{searchController=new AbortController();try{const url=new URL(root.dataset.playerSearch,location.href);url.searchParams.set('q',query);const response=await fetch(url,{headers:{Accept:'application/json'},signal:searchController.signal});if(!response.ok)throw new Error('Player search is unavailable.');const result=await response.json();if(input.value.trim()!==query)return;suggestions.replaceChildren();if(!result.users?.length){suggestions.innerHTML='<span class="table-match__suggestion-note">No matching players found</span>';return;}result.users.forEach(player=>{const option=document.createElement('button');option.type='button';option.className='table-match__suggestion';option.setAttribute('role','option');option.textContent=player.username;option.addEventListener('click',()=>{input.value=player.username;closeSuggestions();input.focus();});suggestions.append(option);});}catch(error){if(error.name!=='AbortError'){closeSuggestions();message.textContent=error.message;}}},180);});document.addEventListener('click',event=>{if(!inviteForm.contains(event.target))closeSuggestions();});inviteForm.addEventListener('submit',async event=>{event.preventDefault();const username=input.value.trim();if(!username)return;button.disabled=true;message.textContent='';try{const response=await fetch(inviteForm.action,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':root.dataset.csrf,'Content-Type':'application/json'},body:JSON.stringify({username})});const result=await response.json();if(!response.ok)throw new Error(result.message||'Could not send invitation.');message.textContent=result.message;input.value='';closeSuggestions();}catch(error){message.textContent=error.message;}finally{button.disabled=false;}});}refresh();const schedule=()=>{pollTimer=setTimeout(async()=>{await refresh();schedule();},document.hidden?3500:1000);};document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});schedule();})();
</script>
@endpush
@push('script')
<script>
(()=>{const root=document.querySelector('#table-match');if(!root)return;const list=document.querySelector('#chat-messages'),empty=document.querySelector('#chat-empty'),error=document.querySelector('#chat-error'),hint=document.querySelector('#chat-hint'),user=Number(root.dataset.user),reactions=['👍','❤️','😂','👏','😮','🎉','👎'];let cursor=0,busy=false,recorder=null,chunks=[];
const headers={'Accept':'application/json','X-CSRF-TOKEN':root.dataset.csrf};
function renderMessage(m){const existing=document.querySelector(`[data-chat-message="${m.id}"]`);if(existing){const bar=existing.querySelector('.table-chat__reactions');bar?.replaceChildren();for(const choice of reactions){const mine=(m.reactions||[]).find(r=>r.emoji===choice);const button=document.createElement('button');button.type='button';button.className=mine?.mine?'is-mine':'';button.textContent=mine?`${choice} ${mine.count}`:choice;button.onclick=()=>react(m.id,choice);bar?.append(button);}return;}empty?.remove();const row=document.createElement('article');row.className='table-chat__message'+(Number(m.user_id)===user?' is-mine':'');row.dataset.chatMessage=m.id;const meta=document.createElement('div');meta.className='table-chat__meta';const name=document.createElement('strong');name.textContent=m.name||'Player';const time=document.createElement('time');time.textContent=new Date(m.time).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});meta.append(name,time);row.append(meta);
if(m.body){const body=document.createElement('p');body.className='table-chat__body';body.textContent=m.body;row.append(body);}if(m.attachment_url){if(m.kind==='voice'){const audio=document.createElement('audio');audio.className='table-chat__audio';audio.controls=true;audio.preload='none';audio.src=m.attachment_url;row.append(audio);}else if((m.attachment_mime||'').startsWith('image/')){const image=document.createElement('img');image.className='table-chat__image';image.src=m.attachment_url;image.alt=m.attachment_name||'Shared image';image.loading='lazy';row.append(image);}const link=document.createElement('a');link.className='table-chat__attachment';link.href=m.attachment_url;link.textContent=(m.kind==='voice'?'🎙️ Voice note: ':'📎 ')+(m.attachment_name||'Open shared file');link.target='_blank';link.rel='noopener';row.append(link);}
const reactionBar=document.createElement('div');reactionBar.className='table-chat__reactions';for(const choice of reactions){const mine=(m.reactions||[]).find(r=>r.emoji===choice);const button=document.createElement('button');button.type='button';button.className=mine?.mine?'is-mine':'';button.textContent=mine?`${choice} ${mine.count}`:choice;button.setAttribute('aria-label',`${choice} reaction`);button.onclick=()=>react(m.id,choice);reactionBar.append(button);}row.append(reactionBar);list.append(row);cursor=Math.max(cursor,Number(m.id));list.scrollTop=list.scrollHeight;}
async function getMessages(){if(busy||document.hidden)return;busy=true;try{const url=new URL(root.dataset.chat,location.href);url.searchParams.set('after',cursor);const response=await fetch(url,{headers,cache:'no-store'});if(!response.ok)throw new Error('Chat could not reconnect.');const data=await response.json();(data.messages||[]).forEach(renderMessage);error.textContent='';}catch(e){error.textContent=e.message;}finally{busy=false;}}
async function react(id,emoji){try{const url=root.dataset.reactionTemplate.replace('__MESSAGE__',id);const response=await fetch(url,{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({emoji})});if(!response.ok)throw new Error('Reaction could not be saved.');const data=await response.json();const card=document.querySelector(`[data-chat-message="${id}"]`),bar=card?.querySelector('.table-chat__reactions');if(!bar)return;bar.replaceChildren();for(const choice of reactions){const item=data.reactions.find(r=>r.emoji===choice);const button=document.createElement('button');button.type='button';button.className=item?.mine?'is-mine':'';button.textContent=item?`${choice} ${item.count}`:choice;button.onclick=()=>react(id,choice);bar.append(button);}}catch(e){error.textContent=e.message;}}
const composer=document.querySelector('#chat-input');function resizeComposer(){composer.style.height='auto';composer.style.height=Math.min(composer.scrollHeight,160)+'px';composer.style.overflowY=composer.scrollHeight>160?'auto':'hidden';}resizeComposer();composer.addEventListener('input',resizeComposer);
async function send(form){error.textContent='';hint.textContent='Sending…';try{const response=await fetch(root.dataset.chatSend,{method:'POST',headers,body:form});const data=await response.json();if(!response.ok)throw new Error(data.message||'Message could not be sent.');renderMessage(data.message);composer.value='';resizeComposer();document.querySelector('#chat-file').value='';hint.textContent='Files up to 10 MB';}catch(e){error.textContent=e.message;hint.textContent='Files up to 10 MB';}}
document.querySelector('#chat-form').addEventListener('submit',event=>{event.preventDefault();const text=composer.value.trim();if(!text)return;const data=new FormData();data.append('body',text);data.append('kind','text');send(data);});composer.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();document.querySelector('#chat-form').requestSubmit();}});document.querySelector('#chat-file').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;const data=new FormData();data.append('attachment',file);data.append('kind','file');send(data);});
const voice=document.querySelector('#chat-voice');voice.addEventListener('click',async()=>{if(recorder?.state==='recording'){recorder.stop();voice.classList.remove('is-recording');voice.querySelector('span').textContent='Voice note';return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){error.textContent='Voice recording is not supported by this browser.';return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};recorder.onstop=()=>{stream.getTracks().forEach(track=>track.stop());const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});if(blob.size>10*1024*1024){error.textContent='Voice notes must be under 10 MB.';return;}const data=new FormData();const mime=blob.type.split(';')[0],extension=mime==='audio/webm'?'weba':mime==='audio/mp4'?'m4a':(mime.split('/')[1]||'ogg');data.append('attachment',blob,`voice-note.${extension}`);data.append('kind','voice');send(data);};recorder.start();voice.classList.add('is-recording');voice.querySelector('span').textContent='Stop recording';hint.textContent='Recording… tap to finish';}catch(e){error.textContent='Allow microphone access to record a voice note.';}});
getMessages();const poll=()=>setTimeout(async()=>{await getMessages();poll();},document.hidden?7000:2500);poll();document.addEventListener('visibilitychange',()=>{if(!document.hidden){getMessages();}});
})();
</script>
@endpush
